function stageMarkup(stages) {
  return stages.map((stage, index) => '<span><b>' + String(index + 1).padStart(2, "0") + '</b>' + escapeHtml(stage) + '</span>').join("");
}

function dijiangReadoutMarkup(data, status) {
  const english = data.locale === "en";
  const output = status.key === "completed" ? "LOCAL / VERIFIED" : status.key === "failed" ? "DELIVERY BLOCKED" : "REVIEW REQUIRED";
  return [
    '<div class="field-readout" aria-label="', english ? "Delivery relay status" : "交付中继状态", '">',
    '<div class="field-readout__head"><span>', english ? "DELIVERY RELAY" : "交付中继", '</span><b>D-0017</b></div>',
    '<div class="field-readout__grid">',
    '<span><small>', english ? "NODE LINK" : "节点链路", '</small><strong>05 / 04</strong></span>',
    '<span><small>', english ? "OUTPUT" : "输出状态", '</small><strong>', output, '</strong></span>',
    '<span><small>', english ? "UPLOAD POLICY" : "上传策略", '</small><strong>LOCAL ONLY</strong></span>',
    '</div></div>',
  ].join("");
}

function defaultStages(locale) {
  return locale === "zh-CN" ? ["提示", "构建", "测试", "捕获", "交付"] : ["PROMPT", "BUILD", "TEST", "CAPTURE", "SHIP"];
}

function normalizePosterData(value) {
  const data = value && typeof value === "object" ? value : {};
  const locale = data.locale === "en" ? "en" : "zh-CN";
  const text = posterText(locale);
  const stages = Array.isArray(data.stages)
    ? data.stages.filter((stage) => typeof stage === "string" && stage.trim()).slice(0, 5)
    : [];
  return {
    ...data,
    locale,
    theme: data.theme === "blue-big-fish" ? "blue-big-fish" : "frontier-signal",
    projectName: String(data.projectName ?? "").trim() || text.untitledProject,
    task: String(data.task ?? "").trim() || text.taskNotRecorded,
    stages: stages.length ? stages : defaultStages(locale),
    image: typeof data.image === "string" ? data.image : "",
    surfaceImage: /^\.\/[A-Za-z0-9._-]+$/.test(String(data.surfaceImage ?? "")) ? String(data.surfaceImage) : "",
  };
}

function normalizeTaskStatus(value) {
  const status = String(value ?? "completed");
  return ["completed", "partial", "failed"].includes(status) ? status : "partial";
}

function normalizeReceiptStatus(value, exitCode) {
  const status = String(value ?? "");
  if (["passed", "failed", "skipped"].includes(status)) return status;
  return Number(exitCode) === 0 ? "passed" : "failed";
}

function statusPresentation(data, text) {
  const key = normalizeTaskStatus(data.taskStatus);
  const copy = text.status[key] ?? text.status.partial;
  return {
    key,
    badge: data.taskStatusLabel || copy.badge,
    summary: copy.summary,
    deliverable: copy.deliverable,
    fieldKicker: copy.fieldKicker,
    fishKicker: copy.fishKicker,
    receipt: copy.receipt,
    manifest: copy.manifest,
    output: copy.output,
    symbol: copy.symbol,
  };
}

function receiptPresentation(receipt, text) {
  const key = normalizeReceiptStatus(receipt.status, receipt.exitCode);
  const copy = text.status[key] ?? text.status.failed;
  return { key, label: receipt.statusLabel || copy.receipt, symbol: copy.symbol };
}

function posterMetricsMarkup(data, text, itemClass = "") {
  const fileCount = Number(data.fileCount) || 0;
  const testCount = Number(data.testCount) || 0;
  const passedTests = Number(data.passedTests) || 0;
  const inferredGitState = String(data.gitRange ?? "").includes("NO_GIT") ? "unavailable" : fileCount ? "changed" : "clean";
  const gitState = ["unavailable", "clean", "changed"].includes(data.gitState) ? data.gitState : inferredGitState;
  const inferredTestState = testCount ? (passedTests < testCount ? "failed" : "configured") : "unconfigured";
  const testState = ["unconfigured", "failed", "configured"].includes(data.testState) ? data.testState : inferredTestState;
  const fileValue = gitState === "unavailable" ? "--" : String(fileCount);
  const fileLabel = gitState === "unavailable" ? text.filesLocal : gitState === "clean" ? text.filesClean : text.files;
  const testValue = testState === "unconfigured" ? "--" : `${passedTests}/${testCount}`;
  const testLabel = testState === "unconfigured" ? text.testsUnconfiguredMetric : testState === "failed" ? text.testsFailedMetric : text.tests;
  const classAttribute = itemClass ? ` class="${itemClass}"` : "";
  return [
    '<div', classAttribute, ' data-metric-state="', gitState, '"><b>', fileValue, '</b><small>', escapeHtml(fileLabel), '</small></div>',
    '<div', classAttribute, ' data-metric-state="', testState, '"><b>', testValue, '</b><small>', escapeHtml(testLabel), '</small></div>',
    '<div', classAttribute, ' data-metric-state="available"><b>', Number(data.redactionCount) || 0, '</b><small>', escapeHtml(text.redactions), '</small></div>',
  ].join("");
}

function statusAriaLabel(locale, label) {
  return locale === "zh-CN" ? "状态：" + label : "Status: " + label;
}

function posterScreenshotItems(data) {
  const candidates = Array.isArray(data.posterScreenshots)
    ? data.posterScreenshots
    : Array.isArray(data.evidenceImages)
      ? data.evidenceImages
      : [];
  return candidates.filter((item) => item
    && typeof item.image === "string"
    && item.image.length > 0
    && typeof item.mimeType === "string"
    && /^image\/(?:png|jpeg|webp)$/i.test(item.mimeType));
}

function posterScreenshotViewports(data) {
  const items = posterScreenshotItems(data);
  if (items.length) return items.map((item) => String(item.label ?? "")).filter(Boolean);
  if (Array.isArray(data.posterScreenshots) || Array.isArray(data.evidenceImages)) return [];
  if (Array.isArray(data.evidenceViewports)) return data.evidenceViewports.filter(Boolean);
  return Array.isArray(data.viewports) ? data.viewports.filter(Boolean) : [];
}

function posterScreenshotCount(data) {
  const items = posterScreenshotItems(data);
  if (items.length || Array.isArray(data.posterScreenshots) || Array.isArray(data.evidenceImages)) return items.length;
  if (Array.isArray(data.evidenceViewports)) return data.evidenceViewports.filter(Boolean).length;
  return Array.isArray(data.viewports) ? data.viewports.filter(Boolean).length : 0;
}

function posterFooterText(data, text) {
  const viewports = posterScreenshotViewports(data);
  const emptyLabel = data.visualProject === false ? text.captureOptionalMeta : text.capturePending;
  return [viewports.length ? viewports.join(" / ") : emptyLabel, text.footer].join(" / ");
}

function evidenceIntegrityMarkup(data, text, compact = false) {
  const isolatedViewports = Array.isArray(data.isolatedEvidenceViewports) ? data.isolatedEvidenceViewports : [];
  const unclassifiedViewports = Array.isArray(data.unclassifiedEvidenceViewports) ? data.unclassifiedEvidenceViewports : [];
  const invalidViewports = Array.isArray(data.invalidEvidenceViewports) ? data.invalidEvidenceViewports : [];
  const matchingCount = posterScreenshotCount(data);
  const totalCount = matchingCount + isolatedViewports.length + unclassifiedViewports.length + invalidViewports.length;
  const screenshotOptional = data.visualProject === false;
  const hasRecords = totalCount > 0;
  const isolatedItems = isolatedViewports.map((viewport, index) => [
    '<li data-state="isolated"><b>', String(index + 1).padStart(2, "0"), '</b><span>', escapeHtml(viewport), '</span><small>', escapeHtml(text.captureIsolatedState), '</small></li>',
  ].join("")).join("");
  const unclassifiedItems = unclassifiedViewports.map((viewport, index) => [
    '<li data-state="unclassified"><b>U', String(index + 1).padStart(2, "0"), '</b><span>', escapeHtml(viewport), '</span><small>', escapeHtml(text.captureUnclassifiedState), '</small></li>',
  ].join("")).join("");
  const invalidItems = invalidViewports.map((viewport, index) => [
    '<li data-state="invalid"><b>I', String(index + 1).padStart(2, "0"), '</b><span>', escapeHtml(viewport), '</span><small>', escapeHtml(text.captureInvalidState), '</small></li>',
  ].join("")).join("");
  const hasIsolated = isolatedViewports.length > 0;
  const hasUnclassified = unclassifiedViewports.length > 0;
  const hasInvalid = invalidViewports.length > 0;
  const title = screenshotOptional
    ? text.captureOptional
    : !hasRecords
      ? text.captureNoRecord
    : hasInvalid && !hasIsolated && !hasUnclassified
    ? text.captureInvalid
    : hasIsolated && (hasUnclassified || hasInvalid)
    ? text.captureFiltered
    : hasUnclassified && hasInvalid
      ? text.captureFiltered
    : hasIsolated
      ? text.captureIsolated
      : hasUnclassified
        ? text.captureUnclassified
        : text.capturePending;
  const detail = screenshotOptional
    ? (hasRecords ? text.captureOptionalRecordDetail : text.captureOptionalDetail)
    : !hasRecords
      ? text.captureNoRecordDetail
    : hasInvalid && !hasIsolated && !hasUnclassified
    ? text.captureInvalidDetail
    : hasIsolated && (hasUnclassified || hasInvalid)
    ? text.captureFilteredDetail
    : hasUnclassified && hasInvalid
      ? text.captureFilteredDetail
    : hasIsolated
      ? text.captureIsolatedDetail
      : hasUnclassified
        ? text.captureUnclassifiedDetail
        : text.capturePendingDetail;
  const pendingCount = isolatedViewports.length + unclassifiedViewports.length + invalidViewports.length;
  const captureState = screenshotOptional
    ? "optional"
    : !hasRecords
      ? "pending"
      : hasInvalid && !hasIsolated && !hasUnclassified
        ? "invalid"
        : hasUnclassified && !hasIsolated && !hasInvalid
          ? "unclassified"
          : hasIsolated && !hasUnclassified && !hasInvalid
            ? "isolated"
            : "filtered";
  const emptyState = screenshotOptional
    ? (hasRecords ? "capture-optional-records" : "capture-optional")
    : !hasRecords
      ? "capture-empty"
      : "capture-pending";
  const records = isolatedItems || unclassifiedItems || invalidItems
    ? '<ol class="evidence-page__guard-list">' + invalidItems + isolatedItems + unclassifiedItems + '</ol>'
    : '<div class="evidence-page__guard-empty" data-empty-state="' + emptyState + '" role="note"><span>CAPTURE SLOT / 00</span><b>' + escapeHtml(screenshotOptional ? text.captureOptionalRecord : text.captureNoRecord) + '</b><small>' + escapeHtml(screenshotOptional ? (hasRecords ? text.captureOptionalRecordDetail : text.captureOptionalDetail) : text.captureNoRecordDetail) + '</small></div>';
  const actionKind = !hasRecords
    ? "empty"
    : hasInvalid
      ? "invalid"
      : hasUnclassified
        ? "unclassified"
        : "isolated";
  const actionTitle = actionKind === "invalid"
    ? text.captureActionInvalid
    : actionKind === "unclassified"
      ? text.captureActionUnclassified
      : actionKind === "isolated"
        ? text.captureActionIsolated
        : text.captureActionEmpty;
  const actionDetail = actionKind === "invalid"
    ? text.captureActionInvalidDetail
    : actionKind === "unclassified"
      ? text.captureActionUnclassifiedDetail
      : actionKind === "isolated"
        ? text.captureActionIsolatedDetail
        : text.captureActionEmptyDetail;
  const actionCount = pendingCount || (matchingCount === 0 ? Math.max(1, Number(data.expectedViewportCount) || 3) : 0);
  const queue = compact || screenshotOptional ? "" : [
    '<div class="evidence-page__guard-action" data-action="', actionKind, '" role="note"><div><small>', escapeHtml(text.captureActionLabel), '</small><strong>', escapeHtml(actionKind === "empty" ? text.captureQueue : actionTitle), '</strong><span>', escapeHtml(data.evidenceThemeName), ' / ', escapeHtml(actionKind === "empty" ? text.captureQueueDetail : actionDetail), '</span></div>',
    '<b>', String(actionCount).padStart(2, "0"), '<small>', escapeHtml(text.captureQueueCount), '</small></b></div>',
  ].join("");
  return [
    '<article class="evidence-page__guard', compact ? ' evidence-page__guard--compact' : '', '" data-capture-state="', captureState, '" data-capture-reason="', escapeHtml(emptyState), '" data-capture-legacy-label="', escapeHtml(text.capturePending), '" role="note"><div class="evidence-page__guard-copy"><small>DSH / THEME INTEGRITY</small><b>', escapeHtml(title), '</b><p>', escapeHtml(detail), '</p></div>',
    '<div class="evidence-page__guard-meta"><span>', escapeHtml(data.evidenceThemeName), '</span><strong>', String(matchingCount).padStart(2, "0"), ' / ', String(totalCount).padStart(2, "0"), '</strong><small>', escapeHtml(screenshotOptional ? text.captureOptionalMeta : text.captureMatched), '</small></div>',
    records, queue, '</article>',
  ].join("");
}

function evidenceMarkup(data, text) {
  const items = posterScreenshotItems(data);
  const hasExcludedEvidence = (data.isolatedEvidenceViewports?.length ?? 0) + (data.unclassifiedEvidenceViewports?.length ?? 0) + (data.invalidEvidenceViewports?.length ?? 0) > 0;
  if (items.length) {
    const figures = items.map((item, index) => [
      '<figure class="evidence-page__item"><div class="shot"><img loading="lazy" src="data:', item.mimeType, ';base64,', item.image, '" alt="', escapeHtml(item.label), '"></div>',
      '<figcaption><b>', String(index + 1).padStart(2, "0"), '</b><span>', escapeHtml(item.label), '</span></figcaption></figure>',
    ].join("")).join("");
    return figures + (hasExcludedEvidence ? evidenceIntegrityMarkup(data, text, true) : "");
  }
  return evidenceIntegrityMarkup(data, text);
}

function evidencePageMarkup(data, text) {
  const matchingCount = posterScreenshotCount(data);
  const totalCount = matchingCount + (data.isolatedEvidenceViewports?.length ?? 0) + (data.unclassifiedEvidenceViewports?.length ?? 0) + (data.invalidEvidenceViewports?.length ?? 0);
  const screenshotOptional = data.visualProject === false && matchingCount === 0;
  return [
    '<section class="evidence-page" aria-label="', escapeHtml(text.evidence), '">',
    '<div class="evidence-page__frame"><header class="evidence-page__head"><div><small>DSH / SHOWCASE</small><h2>', escapeHtml(text.evidence), '</h2></div>',
    '<span>', String(matchingCount).padStart(2, "0"), ' / ', String(totalCount).padStart(2, "0"), ' ', escapeHtml(screenshotOptional ? text.captureOptionalMeta : text.captureMatched), '</span></header>',
    '<div class="evidence-page__grid">', evidenceMarkup(data, text), '</div></div>',
    '<p class="evidence-page__footer mono">', escapeHtml(text.footer), '</p></section>',
  ].join("");
}

function currentRouteMarkup(stages, text) {
  const nodes = stages.map((stage, index) => [
    '<span><b>', String(index + 1).padStart(2, "0"), '</b><em>', escapeHtml(stage), '</em></span>',
  ].join("")).join("");
  return [
    '<section class="current-route" aria-label="', escapeHtml(text.route), '"><header><small>', escapeHtml(text.routeMeta), '</small><b>', escapeHtml(text.route), '</b></header>',
    '<svg class="route-swell" viewBox="0 0 1000 140" preserveAspectRatio="none" aria-hidden="true"><path d="M20 84C144 18 232 120 350 70s206-60 324 0 196 42 306-28"/></svg>',
    '<div class="route-nodes">', nodes, '</div></section>',
  ].join("");
}

function manifestEmptyMarkup(kind, title, detail) {
  return [
    '<li class="manifest-empty" data-empty-state="', escapeHtml(kind), '" role="note"><span><strong>', escapeHtml(title), '</strong><small>', escapeHtml(detail), '</small></span></li>',
  ].join("");
}

function deliveryManifestMarkup(data, text) {
  const status = statusPresentation(data, text);
  const rawGitFiles = (Array.isArray(data.gitFiles) ? data.gitFiles : []).slice(0, 5);
  const untrackedDirectories = rawGitFiles.filter((file) => String(file.path ?? "").endsWith("/") && !(Number(file.additions) || Number(file.deletions)));
  const changedGitFiles = rawGitFiles.filter((file) => !untrackedDirectories.includes(file));
  const inferredGitState = String(data.gitRange ?? "").includes("NO_GIT") ? "unavailable" : rawGitFiles.length ? "changed" : "clean";
  const gitState = ["unavailable", "clean", "changed"].includes(data.gitState) ? data.gitState : inferredGitState;
  const changedGitItems = [
    ...changedGitFiles.map((file) => [
      '<li><span>', escapeHtml(file.path), '</span><b>+', Number(file.additions) || 0, ' / -', Number(file.deletions) || 0, '</b></li>',
    ].join("")),
    ...(untrackedDirectories.length ? [[
      '<li class="manifest-untracked"><span>', escapeHtml(text.manifestUntracked), '</span><b>', String(untrackedDirectories.length).padStart(2, "0"), ' ', escapeHtml(text.manifestFolders), '</b></li>',
    ].join("")] : []),
  ].join("");
  const gitItems = gitState === "unavailable"
    ? manifestEmptyMarkup("git-unavailable", text.gitUnavailableTitle, text.gitUnavailableDetail)
    : gitState === "clean"
      ? manifestEmptyMarkup("git-clean", text.gitCleanTitle, text.gitCleanDetail)
      : changedGitItems || manifestEmptyMarkup("git-details-missing", text.gitChangedMissingTitle, text.gitChangedMissingDetail);
  const gitMeta = gitState === "unavailable" ? text.gitUnavailableMeta : String(data.gitRange ?? "");

  const rawReceipts = (Array.isArray(data.testReceipts) ? data.testReceipts : []).slice(0, 3);
  const inferredTestState = rawReceipts.length ? "configured" : "unconfigured";
  const testState = ["unconfigured", "failed", "configured"].includes(data.testState) ? data.testState : inferredTestState;
  const receiptItems = rawReceipts.map((receipt) => {
    const receiptState = receiptPresentation(receipt, text);
    const exitCode = Number(receipt.exitCode) || 0;
    const ariaLabel = String(receipt.command ?? "") + ": " + receiptState.label + ", " + text.exit + " " + exitCode;
    return [
      '<li data-status="', receiptState.key, '" aria-label="', escapeHtml(ariaLabel), '"><span>', escapeHtml(receipt.command), '</span><b><span aria-hidden="true">', escapeHtml(receiptState.symbol), '</span> ', escapeHtml(receiptState.label), ' · ', escapeHtml(receipt.duration), ' · ', escapeHtml(text.exit), ' ', exitCode, '</b></li>',
    ].join("");
  }).join("");
  const receipts = receiptItems || (testState === "unconfigured"
    ? manifestEmptyMarkup("tests-unconfigured", text.testsUnconfiguredTitle, text.testsUnconfiguredDetail)
    : manifestEmptyMarkup("test-receipts-missing", text.testsMissingTitle, text.testsMissingDetail));
  const testMeta = testState === "unconfigured"
    ? text.testsUnconfiguredMeta
    : String(data.passedTests || 0) + "/" + String(data.testCount || 0) + " " + text.tests;

  const outputEntries = [
    { label: text.manifestReport, path: data.reportPath },
    { label: text.manifestSummary, path: data.summaryPath },
    { label: text.manifestPoster, path: data.posterPath },
  ].filter((entry) => Boolean(entry.path));
  const outputLine = outputEntries.map((entry) => entry.path).join(" → ");
  const outputState = outputEntries.length ? "available" : "empty";
  const outputSteps = outputEntries.length
    ? outputEntries.map((entry) => [
      '<span><i>', escapeHtml(entry.label), '</i><strong>', escapeHtml(entry.path), '</strong></span>',
    ].join("")).join("")
    : '<div class="manifest-output__empty" data-empty-state="outputs-missing" role="note"><strong>' + escapeHtml(text.outputsMissingTitle) + '</strong><small>' + escapeHtml(text.outputsMissingDetail) + '</small></div>';

  const screenshotRecordCount = posterScreenshotCount(data)
    + (data.isolatedEvidenceViewports?.length ?? 0)
    + (data.unclassifiedEvidenceViewports?.length ?? 0)
    + (data.invalidEvidenceViewports?.length ?? 0);
  const screenshotOptional = data.visualProject === false && screenshotRecordCount === 0;
  const checked = Math.max(Number(data.gitFileCount) || 0, (data.gitFiles ?? []).length, (data.testReceipts ?? []).length);
  const scopeItems = [
    { label: gitState === "unavailable" ? text.scopeLocalFiles : text.scopeGit, state: gitState },
    { label: testState === "unconfigured" ? text.scopeTestsUnconfigured : text.scopeTests, state: testState },
    { label: screenshotOptional ? text.scopeScreensOptional : text.scopeScreens, state: screenshotOptional ? "optional" : "required" },
    { label: text.scopePrivacy, state: "available" },
    { label: text.scopeExport, state: outputState },
  ];
  const scope = scopeItems.map((item) => '<span data-scope-state="' + escapeHtml(item.state) + '">' + escapeHtml(item.label) + '</span>').join("");
  const manifestAriaLabel = text.manifest + " / " + status.badge;
  return [
    '<section class="route-evidence delivery-manifest" data-status="', status.key, '" data-git-state="', gitState, '" data-test-state="', testState, '" data-output-state="', outputState, '" aria-label="', escapeHtml(manifestAriaLabel), '"><header><div><small>', escapeHtml(text.manifestMeta), '</small><b>', escapeHtml(text.manifest), '</b></div>',
    '<span data-status="', status.key, '" role="status" aria-label="', escapeHtml(statusAriaLabel(data.locale, status.badge)), '">', String(checked).padStart(2, "0"), ' ', escapeHtml(status.manifest), '</span></header>',
    '<div class="manifest-grid"><article class="manifest-block" data-block-state="', gitState, '"><div class="manifest-block__head"><span>', escapeHtml(text.manifestChanges), '</span><small>', escapeHtml(gitMeta), '</small></div><ul data-empty="', changedGitItems ? 'false' : 'true', '">', gitItems, '</ul></article>',
    '<article class="manifest-block" data-block-state="', testState, '"><div class="manifest-block__head"><span>', escapeHtml(text.manifestReceipts), '</span><small>', escapeHtml(testMeta), '</small></div><ul data-empty="', rawReceipts.length ? 'false' : 'true', '">', receipts, '</ul></article></div>',
    '<div class="manifest-scope"><small>', escapeHtml(text.manifestScope), '</small><div>', scope, '</div></div>',
    '<footer class="manifest-output" data-status="', status.key, '" data-output-state="', outputState, '"><div class="manifest-output__meta"><div class="manifest-output__label"><span>', escapeHtml(text.manifestOutput), '</span><small data-status="', status.key, '" aria-label="', escapeHtml(statusAriaLabel(data.locale, outputLine ? status.output : text.outputsMissingTitle)), '">', escapeHtml(outputLine ? status.output : text.outputsMissingTitle), '</small></div><small class="manifest-output__privacy">', Number(data.redactionCount) || 0, ' ', escapeHtml(text.manifestRedactions), ' / ', escapeHtml(text.manifestLocal), '</small></div><div class="manifest-output__path">', outputSteps, '</div></footer></section>',
  ].join("");
}

