function dijiangSlashedWordMarkup(className) {
  const patternId = className + "-pattern";
  return [
    '<svg class="', className, '" viewBox="0 0 1500 260" preserveAspectRatio="xMidYMid meet" aria-hidden="true">',
    '<defs><pattern id="', patternId, '" width="30" height="30" patternUnits="userSpaceOnUse" patternTransform="rotate(24)"><path d="M0 -12V42M15 -12V42" stroke="#101115" stroke-width="8" stroke-linecap="square" opacity=".82"/></pattern></defs>',
    '<text x="10" y="198" fill="url(#', patternId, ')" stroke="#101115" stroke-opacity=".16" stroke-width="2" paint-order="stroke" font-family="Arial Narrow, Bahnschrift Condensed, Arial, sans-serif" font-size="196" font-weight="900" letter-spacing="9">DIJIANG</text>',
    '<path class="field-slashed-rail" d="M22 226H1160"/>',
    '<path class="field-slashed-rail field-slashed-rail--accent" d="M1182 226h72"/>',
    '</svg>',
  ].join("");
}

function dijiangLoaderInstrumentMarkup() {
  const ticks = Array.from({ length: 24 }, (_, index) => {
    const major = index % 6 === 0;
    const end = major ? 34 : 27;
    return '<line class="instrument-tick' + (major ? ' instrument-tick--major' : '') + '" x1="160" y1="18" x2="160" y2="' + String(end) + '" transform="rotate(' + String(index * 15) + ' 160 160)" />';
  }).join("");
  return [
    '<svg class="field-loader-instrument" viewBox="0 0 320 320" preserveAspectRatio="xMidYMid meet" aria-hidden="true">',
    '<circle class="instrument-halo" cx="160" cy="160" r="148" />',
    '<circle class="instrument-ring instrument-ring--outer" cx="160" cy="160" r="136" />',
    '<circle class="instrument-ring instrument-ring--inner" cx="160" cy="160" r="106" />',
    '<circle class="instrument-ring instrument-ring--core" cx="160" cy="160" r="54" />',
    '<g class="instrument-ticks">', ticks, '</g>',
    '<path class="instrument-cross" d="M160 38V282M38 160H282" />',
    '<path class="instrument-sweep" d="M160 160L160 31" />',
    '<circle class="instrument-node" cx="160" cy="160" r="9" />',
    '<circle class="instrument-node instrument-node--signal" cx="160" cy="31" r="4" />',
    '<text class="instrument-label instrument-label--top" x="160" y="78">D-0017</text>',
    '<text class="instrument-label instrument-label--bottom" x="160" y="248">LINK / 04</text>',
    '</svg>',
  ].join("");
}

