    '<path class="loader-diagram__tower" d="M188 376V126h82v250M188 174h82M188 224h82M188 274h82M188 324h82M208 126V88h42v38M229 88V52"/>',
    '<path class="loader-diagram__beam" d="M72 376H454M116 334H396M94 292H358M290 376V206h72M362 206l78-52M362 236l104 62"/>',
    '<circle class="loader-diagram__node" cx="229" cy="52" r="7"/><circle class="loader-diagram__node" cx="440" cy="154" r="5"/><circle class="loader-diagram__node" cx="466" cy="298" r="5"/>',
    '<text x="34" y="40">D-0017 / INDUSTRIAL RELAY</text><text x="350" y="397">GRID / 04</text>',
    '</svg>',
    '<div class="field-loader-copy"><span class="field-loader-kicker">', escapeHtml(text.fieldTheme), ' / ', escapeHtml(text.loading), '</span>',
    '<strong title="', escapeHtml(loaderProjectName), '">', escapeHtml(loaderProjectName), '</strong><div class="field-loader-calibration" aria-hidden="true"><i></i><i></i><i></i></div></div>',
    '<div class="field-loader-readout"><span>BOOT SEQUENCE / LOCAL ONLY</span><b data-loader-percent>00%</b><i class="field-loader-progress"><em data-loader-fill></em></i></div>',
